//! Pixel checks against paths generated by the pinned, unmodified Lisse core.
//! PNGs use Cairo coverage AA; niri retains its one-pixel smoothstep AA.
use std::fs::File;
use std::io::Cursor;

use niri_config::{
    BackgroundEffect as ConfigEffect, Color, CornerRadius, GradientInterpolation, LiquidGlass,
};
use smithay::backend::allocator::Fourcc;
use smithay::backend::renderer::element::{Kind, RenderElement};
use smithay::backend::renderer::gles::GlesRenderer;
use smithay::backend::renderer::{Color32F, ExportMem};
use smithay::utils::{Logical, Rectangle, Scale, Transform};

use super::gpu;
use crate::render_helpers::background_effect::{BackgroundEffect, RenderParams};
use crate::render_helpers::border::BorderRenderElement;
use crate::render_helpers::shadow::ShadowRenderElement;
use crate::render_helpers::solid_color::{SolidColorBuffer, SolidColorRenderElement};
use crate::render_helpers::xray::{Xray, XrayPos};
use crate::render_helpers::{blend, RenderCtx, RenderTarget};

fn geometry() -> Rectangle<f64, Logical> {
    Rectangle::from_size((240., 160.).into())
}

fn radius(radii: [f32; 4], smoothing: f32) -> CornerRadius {
    CornerRadius {
        top_left: radii[0],
        top_right: radii[1],
        bottom_right: radii[2],
        bottom_left: radii[3],
        smoothing,
    }
}

fn border(corner: CornerRadius, scale: f64, width: f32) -> BorderRenderElement {
    BorderRenderElement::new(
        geometry().size,
        geometry(),
        GradientInterpolation::default(),
        Color::from_rgba8_unpremul(255, 255, 255, 255),
        Color::from_rgba8_unpremul(255, 255, 255, 255),
        0.,
        geometry(),
        width,
        corner,
        scale as f32,
        1.,
    )
}

fn pixels(
    renderer: &mut GlesRenderer,
    scale: f64,
    elements: &[impl RenderElement<GlesRenderer>],
) -> Vec<u8> {
    let size: smithay::utils::Size<i32, smithay::utils::Physical> =
        geometry().size.to_physical_precise_round(scale);
    gpu::render_offscreen_audited(renderer, size, scale, elements).unwrap();
    let mapping = crate::render_helpers::render_and_download(
        renderer,
        size,
        Scale::from(scale),
        Transform::Normal,
        Fourcc::Abgr8888,
        elements.iter(),
    )
    .unwrap();
    renderer.map_texture(&mapping).unwrap().to_vec()
}

fn reference(bytes: &[u8]) -> Vec<u8> {
    let mut decoder = png::Decoder::new(Cursor::new(bytes)).read_info().unwrap();
    let mut pixels = vec![0; decoder.output_buffer_size().unwrap()];
    let info = decoder.next_frame(&mut pixels).unwrap();
    assert_eq!(info.color_type, png::ColorType::Rgba);
    pixels.truncate(info.buffer_size());
    pixels
}

fn record(name: &str, scale: f64, pixels: &[u8]) {
    if let Some(directory) = std::env::var_os("NIRI_CORNER_COMPARE_DIR") {
        let directory = std::path::PathBuf::from(directory);
        std::fs::create_dir_all(&directory).unwrap();
        let size: smithay::utils::Size<i32, smithay::utils::Physical> =
            geometry().size.to_physical_precise_round(scale);
        let mut encoder = png::Encoder::new(
            File::create(directory.join(format!("{name}.png"))).unwrap(),
            size.w as u32,
            size.h as u32,
        );
        encoder.set_color(png::ColorType::Rgba);
        encoder.set_depth(png::BitDepth::Eight);
        encoder
            .write_header()
            .unwrap()
            .write_image_data(pixels)
            .unwrap();
    }
}

#[test]
fn smooth_mask_matches_lisse_at_shoulders_arcs_and_fractional_scale() {
    let Some(mut renderer) = gpu::gles_renderer() else {
        return;
    };
    let cases: [(&str, f64, [f32; 4], f32, &[u8]); 5] = [
        (
            "uniform-065",
            1.,
            [40.; 4],
            0.65,
            include_bytes!("fixtures/smooth-corners/uniform-065.png"),
        ),
        (
            "uniform-001",
            1.,
            [40.; 4],
            0.01,
            include_bytes!("fixtures/smooth-corners/uniform-001.png"),
        ),
        (
            "uniform-100",
            1.,
            [40.; 4],
            1.,
            include_bytes!("fixtures/smooth-corners/uniform-100.png"),
        ),
        (
            "fractional-065",
            1.75,
            [40.; 4],
            0.65,
            include_bytes!("fixtures/smooth-corners/fractional-065.png"),
        ),
        (
            "asymmetric-065",
            1.75,
            [48., 20., 0., 32.],
            0.65,
            include_bytes!("fixtures/smooth-corners/asymmetric-065.png"),
        ),
    ];
    for (name, scale, radii, smoothing, bytes) in cases {
        let actual = pixels(
            &mut renderer,
            scale,
            &[border(radius(radii, smoothing), scale, 0.)],
        );
        let expected = reference(bytes);
        assert_eq!(actual.len(), expected.len());
        let delta: Vec<_> = actual
            .chunks_exact(4)
            .zip(expected.chunks_exact(4))
            .map(|(a, b)| a[3].abs_diff(b[3]))
            .collect();
        let max = *delta.iter().max().unwrap();
        let mean = delta.iter().map(|v| f64::from(*v)).sum::<f64>() / delta.len() as f64;
        eprintln!("{name}: alpha max delta={max}, mean={mean:.4}/255");
        record(name, scale, &actual);
        assert!(
            max <= 40 && mean < 0.3,
            "{name}: contour disagrees with Lisse, max {max}, mean {mean}"
        );
        // Coverage remains premultiplied, including points near shoulder/arc joins.
        assert!(actual
            .chunks_exact(4)
            .all(|p| p[..3].iter().all(|v| *v <= p[3])));
    }
}

#[test]
fn smooth_glass_border_and_shadow_share_mask_in_sdr_and_hdr() {
    let Some(mut renderer) = gpu::gles_renderer() else {
        return;
    };
    let corner = radius([40.; 4], 0.65);
    for output in [None, Some((203., 400.))] {
        blend::set_frame_blend(&mut renderer, output);
        for scale in [1., 1.75] {
            let filled = pixels(&mut renderer, scale, &[border(corner, scale, 0.)]);
            let shadow = ShadowRenderElement::new(
                geometry().size,
                geometry(),
                Color::from_rgba8_unpremul(255, 255, 255, 255),
                0.,
                corner,
                scale as f32,
                Rectangle::zero(),
                CornerRadius::default(),
                1.,
            );
            assert!(
                pixels(&mut renderer, scale, &[shadow]) == filled,
                "hard shadow mask differs"
            );
            let mut xray = Xray::new();
            xray.workspaces.push((geometry(), Color32F::TRANSPARENT));
            for buffer in [&xray.background[0]] {
                let mut buffer = buffer.borrow_mut();
                buffer.update_size(
                    geometry().size.to_physical_precise_round(scale),
                    Scale::from(scale),
                );
                let solid = SolidColorBuffer::new(geometry().size, [1., 1., 1., 1.]);
                buffer.elements::<GlesRenderer>().push(
                    SolidColorRenderElement::from_buffer(&solid, (0., 0.), 1., Kind::Unspecified)
                        .into(),
                );
            }
            let mut effect = BackgroundEffect::new();
            effect.update_render_elements(
                corner,
                ConfigEffect {
                    xray: Some(true),
                    liquid_glass: Some(LiquidGlass {
                        refraction_strength: 0.,
                        glow_weight: 0.,
                        edge_lighting: 0.,
                        lens_distortion: 0.,
                        saturation: 1.,
                        vibrancy: 0.,
                        ..Default::default()
                    }),
                    ..Default::default()
                },
                false,
            );
            let mut glass = Vec::new();
            effect.render(
                RenderCtx {
                    renderer: &mut renderer,
                    xray: Some(&xray),
                    target: RenderTarget::Output,
                },
                None,
                RenderParams {
                    geometry: geometry(),
                    subregion: None,
                    clip: Some((geometry(), corner)),
                    scale,
                },
                XrayPos::new((0., 0.).into(), 1.),
                &mut |elem| glass.push(elem),
            );
            assert!(!glass.is_empty());
            let actual = pixels(&mut renderer, scale, &glass);
            // The base background path deliberately expands the clip radius by one
            // logical pixel to suppress bleed. Compare that existing policy explicitly.
            let background_mask = pixels(
                &mut renderer,
                scale,
                &[border(corner.expanded_by(1.), scale, 0.)],
            );
            let max = actual
                .iter()
                .zip(&background_mask)
                .map(|(a, b)| a.abs_diff(*b))
                .max()
                .unwrap();
            eprintln!("neutral Glass vs filled mask scale={scale} HDR={output:?}, max={max}");
            record(
                &format!("glass-{scale}-{}", output.is_some()),
                scale,
                &actual,
            );
            record(
                &format!("filled-{scale}-{}", output.is_some()),
                scale,
                &background_mask,
            );
            assert!(
                max <= 1,
                "neutral glass color/mask differs at {scale} HDR={output:?}, max={max}"
            );
            let outlined = pixels(&mut renderer, scale, &[border(corner, scale, 2.)]);
            assert!(outlined
                .chunks_exact(4)
                .all(|p| p[..3].iter().all(|v| *v <= p[3])));
            assert_eq!(outlined[(80 * (240. * scale) as usize + 120) * 4 + 3], 0);
        }
    }
}

#[test]
fn thick_inner_border_and_oversized_shadow_keep_valid_smooth_geometry() {
    let Some(mut renderer) = gpu::gles_renderer() else {
        return;
    };
    // Before re-fitting the inset, its 90px radius exceeded its 20px height,
    // producing negative cubic control distances and breaking shadow inversion.
    let corner = radius([160., 0., 0., 0.], 1.);
    let actual = pixels(&mut renderer, 1., &[border(corner, 1., 70.)]);
    let alpha = |x: usize, y: usize| actual[(y * 240 + x) * 4 + 3];
    assert_eq!(
        alpha(71, 71),
        255,
        "inner rounded corner unexpectedly cut away the border"
    );
    assert_eq!(
        alpha(120, 80),
        0,
        "inner contour failed to cut out the center"
    );
    assert_eq!(alpha(230, 80), 255);
    for sigma in [0., 4.] {
        let make_shadow = |corner| {
            ShadowRenderElement::new(
                geometry().size,
                geometry(),
                Color::from_rgba8_unpremul(255, 255, 255, 255),
                sigma,
                corner,
                1.,
                Rectangle::zero(),
                CornerRadius::default(),
                1.,
            )
        };
        let oversized = radius([960., 0., 0., 0.], 1.);
        let fitted = oversized.fit_to(240., 160.);
        assert!(
            pixels(&mut renderer, 1., &[make_shadow(oversized)])
                == pixels(&mut renderer, 1., &[make_shadow(fitted)]),
            "shadow contour differs after CSS fitting, sigma={sigma}"
        );
    }
}

#[test]
fn fractional_border_inner_edge_matches_pixel_area_coverage() {
    let Some(mut renderer) = gpu::gles_renderer() else {
        return;
    };
    // A 2px border with the compositor's 0.5px corner bleed allowance,
    // at the user's fractional output scale. Lisse paths are independently
    // rasterized at 8x and box-filtered; the inner curve is translated by 2.5px.
    let actual = pixels(
        &mut renderer,
        1.75,
        &[border(radius([40.; 4], 0.65), 1.75, 2.5)],
    );
    let expected = reference(include_bytes!("fixtures/smooth-corners/border-175.png"));
    record("border-175", 1.75, &actual);
    let differences: Vec<_> = actual
        .chunks_exact(4)
        .zip(expected.chunks_exact(4))
        .map(|(a, b)| a[3].abs_diff(b[3]))
        .collect();
    let max = *differences.iter().max().unwrap();
    let mean = differences.iter().map(|v| f64::from(*v)).sum::<f64>() / differences.len() as f64;
    eprintln!("border-175 coverage: max {max}, mean {mean:.4}/255");
    assert!(
        max <= 12,
        "border pixel coverage mismatch: max {max}, mean {mean}"
    );
}
